javascript:(() => { const ID = '__viewport_size_bookmarklet__'; const existing = document.getElementById(ID); if (existing) { if (typeof existing.__dispose === 'function') existing.__dispose(); return; } const host = document.createElement('div'); host.id = ID; host.style.cssText = 'all:initial;position:fixed;top:16px;right:16px;z-index:2147483647;'; const shadow = host.attachShadow({ mode: 'open' }); shadow.innerHTML = ` <style> :host { all:initial; position:fixed; z-index:2147483647; font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; color:#480909; } * { box-sizing:border-box; } .panel { min-width:238px; max-width:90vw; overflow:hidden; border:1px solid rgba(150,0,0,.48); border-radius:10px; background:rgba(255,80,80,.25); box-shadow:0 5px 20px rgba(70,0,0,.18); backdrop-filter:blur(5px); -webkit-backdrop-filter:blur(5px); font-size:13px; } .header { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:7px 9px 7px 11px; background:rgba(230,0,0,.09); cursor:grab; user-select:none; touch-action:none; } .header:active { cursor:grabbing; } .title { font-weight:700; letter-spacing:.01em; } button { font:inherit; cursor:pointer; color:#5b0909; } .close { width:23px; height:23px; padding:0; border:1px solid rgba(125,0,0,.25); border-radius:6px; background:rgba(255,255,255,.42); font-weight:800; line-height:1; } .content { padding:10px 11px 9px; } .nums { display:flex; align-items:center; flex-wrap:wrap; gap:5px; font-variant-numeric:tabular-nums; } .number { display:inline-block; min-width:2ch; font-size:16px; font-weight:750; cursor:pointer; text-decoration:underline dotted rgba(100,0,0,.55); text-underline-offset:3px; } .label { opacity:.82; } .hint { margin-top:5px; font-size:11px; opacity:.78; } .editor { display:none; align-items:end; gap:7px; flex-wrap:wrap; } .field { display:flex; flex-direction:column; gap:3px; font-size:11px; } input { width:82px; padding:5px 6px; border:1px solid rgba(130,0,0,.35); border-radius:5px; background:rgba(255,255,255,.78); color:#3f0808; font:600 13px system-ui,sans-serif; } .resize { padding:6px 10px; border:1px solid rgba(130,0,0,.36); border-radius:6px; background:rgba(255,255,255,.62); font-weight:700; } .status { min-height:1em; margin-top:7px; font-size:11px; opacity:.88; overflow-wrap:anywhere; } </style> <section class="panel" role="dialog" aria-label="Viewport dimensions"> <div class="header"> <span class="title">Viewport size</span> <button class="close" type="button" aria-label="Close" title="Close">×</button> </div> <div class="content"> <div class="nums" title="Double-click either number to edit both dimensions"> <span class="label">W</span><span class="number width-value">0</span><span>px</span> <span style="opacity:.55">×</span> <span class="label">H</span><span class="number height-value">0</span><span>px</span> </div> <div class="editor"> <label class="field">Width (px)<input class="width-input" type="number" min="100" max="10000" step="1" inputmode="numeric"></label> <label class="field">Height (px)<input class="height-input" type="number" min="100" max="10000" step="1" inputmode="numeric"></label> <button class="resize" type="button">Resize</button> </div> <div class="hint">Double-click a number to set a target size.</div> <div class="status" aria-live="polite"></div> </div> </section>`; (document.body || document.documentElement).appendChild(host); const $ = selector => shadow.querySelector(selector); const widthValue = $('.width-value'); const heightValue = $('.height-value'); const nums = $('.nums'); const editor = $('.editor'); const widthInput = $('.width-input'); const heightInput = $('.height-input'); const status = $('.status'); const header = $('.header'); const panel = $('.panel'); let editing = false; let dragging = false; let pointerStartX = 0, pointerStartY = 0, panelStartX = 0, panelStartY = 0; function updateDimensions() { if (!editing) { widthValue.textContent = window.innerWidth; heightValue.textContent = window.innerHeight; } } function exitEdit() { editing = false; nums.style.display = 'flex'; editor.style.display = 'none'; status.textContent = ''; updateDimensions(); } function enterEdit() { editing = true; widthInput.value = window.innerWidth; heightInput.value = window.innerHeight; nums.style.display = 'none'; editor.style.display = 'flex'; status.textContent = ''; widthInput.focus(); widthInput.select(); } function resizeWindow() { const w = Number(widthInput.value); const h = Number(heightInput.value); if (!Number.isInteger(w) || !Number.isInteger(h) || w < 100 || h < 100 || w > 10000 || h > 10000) { status.textContent = 'Enter whole-number dimensions from 100 to 10,000 px.'; return; } const opened = window.open(location.href, '_blank', `popup=yes,width=${w},height=${h},resizable=yes,scrollbars=yes`); if (!opened) status.textContent = 'Popup blocked. Allow pop-ups for this site, then click Resize again.'; else status.textContent = `Requested a new window at ${w} × ${h} px.`; } function dispose() { window.removeEventListener('resize', updateDimensions); host.remove(); } host.__dispose = dispose; widthValue.addEventListener('dblclick', enterEdit); heightValue.addEventListener('dblclick', enterEdit); $('.resize').addEventListener('click', resizeWindow); $('.close').addEventListener('click', dispose); [widthInput, heightInput].forEach(input => input.addEventListener('keydown', event => { if (event.key === 'Escape') exitEdit(); if (event.key === 'Enter') resizeWindow(); })); window.addEventListener('resize', updateDimensions, { passive: true }); header.addEventListener('pointerdown', event => { if (event.target.closest('button')) return; dragging = true; const rect = host.getBoundingClientRect(); host.style.left = `${rect.left}px`; host.style.top = `${rect.top}px`; host.style.right = 'auto'; pointerStartX = event.clientX; pointerStartY = event.clientY; panelStartX = rect.left; panelStartY = rect.top; header.setPointerCapture(event.pointerId); event.preventDefault(); }); header.addEventListener('pointermove', event => { if (!dragging) return; const rect = host.getBoundingClientRect(); const left = Math.max(0, Math.min(window.innerWidth - rect.width, panelStartX + event.clientX - pointerStartX)); const top = Math.max(0, Math.min(window.innerHeight - rect.height, panelStartY + event.clientY - pointerStartY)); host.style.left = `${left}px`; host.style.top = `${top}px`; }); const stopDrag = () => { dragging = false; }; header.addEventListener('pointerup', stopDrag); header.addEventListener('pointercancel', stopDrag); updateDimensions(); })();
